create or replace function public.assign_question_to_final(p_event_id uuid,p_question_id uuid,p_canonical_order smallint) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin if auth.uid() is null or not private.is_event_admin(p_event_id) then raise exception 'forbidden'; end if; if p_canonical_order not between 1 and 10 then raise exception 'Final question order must be 1-10'; end if; if exists(select 1 from public.events where id=p_event_id and status in ('final','completed','archived')) then raise exception 'Final question set is locked'; end if; if not exists(select 1 from public.questions where id=p_question_id and event_id=p_event_id and status='approved') then raise exception 'Only approved questions from this event may be assigned'; end if; if exists(select 1 from public.round_questions rq join public.rounds r on r.id=rq.round_id where rq.question_id=p_question_id and r.event_id=p_event_id) then raise exception 'Question already reserved for a preliminary round'; end if; if exists(select 1 from public.final_questions where event_id=p_event_id and question_id=p_question_id) then raise exception 'Question already assigned to final'; end if; if exists(select 1 from public.final_questions where event_id=p_event_id and canonical_order=p_canonical_order) then raise exception 'Final position already occupied'; end if; if(select count(*) from public.final_questions where event_id=p_event_id)>=10 then raise exception 'Final already has 10 questions'; end if; insert into public.final_questions(event_id,question_id,canonical_order) values(p_event_id,p_question_id,p_canonical_order); insert into public.audit_events(event_id,actor_user_id,event_type,action,metadata) values(p_event_id,auth.uid(),'question','assign_question_to_final',jsonb_build_object('question_id',p_question_id,'canonical_order',p_canonical_order)); end; $$;
create or replace function public.remove_question_from_final(p_event_id uuid,p_question_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin if auth.uid() is null or not private.is_event_admin(p_event_id) then raise exception 'forbidden'; end if; if exists(select 1 from public.events where id=p_event_id and status in ('final','completed','archived')) then raise exception 'Final question set is locked'; end if; delete from public.final_questions where event_id=p_event_id and question_id=p_question_id; insert into public.audit_events(event_id,actor_user_id,event_type,action,metadata) values(p_event_id,auth.uid(),'question','remove_question_from_final',jsonb_build_object('question_id',p_question_id)); end; $$;
create or replace function public.validate_final_question_set(p_event_id uuid) returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$ declare n int; begin if auth.uid() is null or not private.is_event_admin(p_event_id) then raise exception 'forbidden'; end if; select count(*) into n from public.final_questions where event_id=p_event_id; if n<>10 then raise exception 'Exactly 10 final questions are required'; end if; return true; end; $$;
revoke all on function public.assign_question_to_final(uuid,uuid,smallint) from public,anon; revoke all on function public.remove_question_from_final(uuid,uuid) from public,anon; revoke all on function public.validate_final_question_set(uuid) from public,anon; grant execute on function public.assign_question_to_final(uuid,uuid,smallint) to authenticated; grant execute on function public.remove_question_from_final(uuid,uuid) to authenticated; grant execute on function public.validate_final_question_set(uuid) to authenticated;
